def count_bits(n):
    ans = [0] * (n + 1)
    for i in range(1, n + 1):
        ans[i] = ans[i >> 1] + (i & 1)
    return ans

def is_palindrome(x):
    if x < 0:
        return False
    s = str(x)
    return s == s[::-1]

def my_sqrt(x):
    if x < 0:
        return None
    lo, hi = 0, x
    while lo <= hi:
        m = (lo + hi) // 2
        if m * m <= x < (m + 1) * (m + 1):
            return m
        if m * m < x:
            lo = m + 1
        else:
            hi = m - 1
    return 0

def diagonal_sum(mat):
    n = len(mat)
    s = 0
    for i in range(n):
        s += mat[i][i]
        if n - 1 - i != i:
            s += mat[i][n - 1 - i]
    return s

