def climb_stairs(n):
    if n <= 2:
        return n
    a, b = 1, 2
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

def rob(nums):
    prev1 = prev2 = 0
    for v in nums:
        prev1, prev2 = max(prev2 + v, prev1), prev1
    return prev1

def contains_duplicate(nums):
    seen = set()
    for v in nums:
        if v in seen:
            return True
        seen.add(v)
    return False

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

from collections import deque
def oranges_rotting(grid):
    rows, cols = len(grid), len(grid[0])
    q = deque()
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                q.append((r, c, 0))
            elif grid[r][c] == 1:
                fresh += 1
    minutes = 0
    while q:
        r, c, t = q.popleft()
        minutes = max(minutes, t)
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                grid[nr][nc] = 2
                fresh -= 1
                q.append((nr, nc, t + 1))
    return minutes if fresh == 0 else -1

def coin_change(coins, amount):
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] <= amount else -1

def unique_paths(m, n):
    row = [1] * n
    for _ in range(1, m):
        for c in range(1, n):
            row[c] += row[c - 1]
    return row[-1]

def min_distance(word1, word2):
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i-1] == word2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]

def can_jump(nums):
    reach = 0
    for i, v in enumerate(nums):
        if i > reach:
            return False
        reach = max(reach, i + v)
    return True

from collections import Counter
def least_interval(tasks, n):
    freq = Counter(tasks)
    max_count = max(freq.values())
    num_max = sum(1 for v in freq.values() if v == max_count)
    return max(len(tasks), (max_count - 1) * (n + 1) + num_max)

def single_number(nums):
    res = 0
    for v in nums:
        res ^= v
    return res

def reverseBits(n):
    r=0
    for _ in range(32):
        r=(r<<1)|(n&1); n>>=1
    return r

def reverse_integer(x):
    sign = -1 if x < 0 else 1
    x = abs(x)
    res = 0
    while x:
        res = res * 10 + x % 10
        x //= 10
        if res > 2**31 - 1:
            return 0
    return sign * res

def is_palindrome_number(x):
    if x < 0:
        return False
    orig, rev = x, 0
    while x:
        rev = rev * 10 + x % 10
        x //= 10
    return orig == rev

def valid_anagram(s, t):
    from collections import Counter
    return Counter(s) == Counter(t)

def canAttend(intervals):
    intervals=sorted(intervals)
    return all(intervals[i][1]<=intervals[i+1][0] for i in range(len(intervals)-1))

def rob(nums):
    prev2=prev1=0
    for x in nums:
        cur=max(prev1, prev2+x)
        prev2,prev1=prev1,cur
    return prev1

def coinChange(coins, amount):
    INF=amount+1
    dp=[0]+[INF]*amount
    for a in range(1, amount+1):
        for c in coins:
            if c<=a: dp[a]=min(dp[a], dp[a-c]+1)
    return -1 if dp[amount]==INF else dp[amount]

def longestConsecutive(nums):
    s=set(nums); best=0
    for x in s:
        if x-1 not in s:
            y=x
            while y in s: y+=1
            best=max(best, y-x)
    return best

def intersect(nums1,nums2):
    from collections import Counter
    c=Counter(nums1); out=[]
    for x in nums2:
        if c[x]>0: c[x]-=1; out.append(x)
    return out

def thirdMax(nums):
    s=sorted(set(nums))
    return s[-3] if len(s)>=3 else s[-1]

def titleToNumber(columnTitle):
    n=0
    for ch in columnTitle:
        n=n*26+(ord(ch)-64)
    return n

def findMaxAverage(nums,k):
    s=sum(nums[:k]); best=s
    for i in range(k,len(nums)):
        s+=nums[i]-nums[i-k]
        best=max(best,s)
    return best/k

def findContentChildren(g,s_):
    g=sorted(g); s_=sorted(s_); i=j=0
    while i<len(g) and j<len(s_):
        if s_[j]>=g[i]: i+=1
        j+=1
    return i

def twoCitySchedCost(costs):
    costs=sorted(costs,key=lambda c:c[0]-c[1])
    n=len(costs)//2
    return sum(c[0] for c in costs[:n])+sum(c[1] for c in costs[n:])

def mergeAlternately(word1,word2):
    out=[]
    for i in range(max(len(word1),len(word2))):
        if i<len(word1): out.append(word1[i])
        if i<len(word2): out.append(word2[i])
    return ''.join(out)

def majorityElement(nums):
    from collections import Counter
    n=len(nums); t=n//3
    return sorted([k for k,v in Counter(nums).items() if v>t])

def restoreString(s,indices):
    a=['']*len(s)
    for i,ch in enumerate(s): a[indices[i]]=ch
    return ''.join(a)

def numIdenticalPairs(nums):
    from collections import Counter
    return sum(v*(v-1)//2 for v in Counter(nums).values())

def minCostClimbingStairs(cost):
    a=b=0
    for c in cost:
        a,b=b,min(a,b)+c
    return min(a,b)

