    nums = ast.literal_eval(data[0].split("=", 1)[1].strip())
    target = int(data[1].split("=", 1)[1].strip())
    nums.sort()
    n = len(nums)
    res = []
    for i in range(n - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            l, r = j + 1, n - 1
